INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cac0d17d-9030-58c1-acd2-5e70d4826d29', 'Russia On approval of the Concept for the development', 'On approval of the Concept for the development of public non-financial reporting', 'The document sets the development stages of public non-financial reporting, uncovers its purpose and contents, and specifies the issues of control and quality assessment. The concept enforcement will consist of four stages. In 2017-2018 there will be undertaking awareness raising about the concept among expert community, Russian business and society in general, necessary regulatory and methodological basis will be provided, and tools for independent evaluation of organizations’ activities will be developed. The second stage (2019-2020) among other issues implies incorporation of government-owned corporations, government-owned enterprises and public companies into the list of organizations subject to publication of non-financial reporting. The third and the fourth stages will be devoted to the enlargement of the list of organizations subject to providing non-financial reports. Thus, starting from 2023, into the list of companies obliged to publish non-financial reporting there will be included 500 largest organizations, total revenue of which corresponds the requirements of leading Russian ratings.', 'The document sets the development stages of public non-financial reporting, uncovers its purpose and contents, and specifies the issues of control and quality assessment. The concept enforcement will consist of four stages. In 2017-2018 there will be undertaking awareness raising about the concept among expert community, Russian business and society in general, necessary regulatory and methodological basis will be provided, and tools for independent evaluation of organizations’ activities will be developed. The second stage (2019-2020) among other issues implies incorporation of government-owned corporations, government-owned enterprises and public companies into the list of organizations subject to publication of non-financial reporting. The third and the fourth stages will be devoted to the enlargement of the list of organizations subject to providing non-financial reports. Thus, starting from 2023, into the list of companies obliged to publish non-financial reporting there will be included 500 largest organizations, total revenue of which corresponds the requirements of leading Russian ratings.', 'The document sets the development stages of public non-financial reporting, uncovers its purpose and contents, and specifies the issues of control and quality assessment. The concept enforcement will consist of four stages. In 2017-2018 there will be undertaking awareness raising about the concept among expert community, Russian business and society in general, necessary regulatory and methodological basis will be provided, and tools for independent evaluation of organizations’ activities will be developed. The second stage (2019-2020) among other issues implies incorporation of government-owned corporations, government-owned enterprises and public companies into the list of organizations subject to publication of non-financial reporting. The third and the fourth stages will be devoted to the enlargement of the list of organizations subject to providing non-financial reports. Thus, starting from 2023, into the list of companies obliged to publish non-financial reporting there will be included 500 largest organizations, total revenue of which corresponds the requirements of leading Russian ratings.', 'Russia', 'climate', 'in_force', '2018-01-01'::date, 'Russia', 'https://www.carrotsandsticks.org/policies/150_6', ARRAY['russia', 'sdg11', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bb4a5080-dfb5-54fb-b4ff-4691ffa4a2c8', 'Russia Provision of Central Bank of the Russion Federation', 'Provision of Central Bank of the Russion Federation about disclosure of information by issuers of issued securities', 'This provision regulates structure, procedure and terms of obligatory disclosures of information by joint-stock company, disclosures of information on release (additional release) of issued securities (further - securities), disclosures of information in the form of securities prospectus, consolidated financial statements of the issuer of securities, the quarterly report of the issuer of securities (further - the quarterly report) and messages on essential facts of the issuer of securities (further - messages on essential facts), and also establishes requirements to procedure for disclosure by issuers of other informaiton on obligation fulfillment of the issuer and implementation of the rights on the placed securities.', 'This provision regulates structure, procedure and terms of obligatory disclosures of information by joint-stock company, disclosures of information on release (additional release) of issued securities (further - securities), disclosures of information in the form of securities prospectus, consolidated financial statements of the issuer of securities, the quarterly report of the issuer of securities (further - the quarterly report) and messages on essential facts of the issuer of securities (further - messages on essential facts), and also establishes requirements to procedure for disclosure by issuers of other informaiton on obligation fulfillment of the issuer and implementation of the rights on the placed securities.', 'This provision regulates structure, procedure and terms of obligatory disclosures of information by joint-stock company, disclosures of information on release (additional release) of issued securities (further - securities), disclosures of information in the form of securities prospectus, consolidated financial statements of the issuer of securities, the quarterly report of the issuer of securities (further - the quarterly report) and messages on essential facts of the issuer of securities (further - messages on essential facts), and also establishes requirements to procedure for disclosure by issuers of other informaiton on obligation fulfillment of the issuer and implementation of the rights on the placed securities.', 'Russia', 'climate', 'in_force', '2014-01-01'::date, 'Russia', 'https://www.carrotsandsticks.org/policies/150_1', ARRAY['russia', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a6ec619d-7bc1-5583-bb4c-9b374bf34c26', 'Russia Corporate Governance Code', 'Corporate Governance Code, 2014', 'This Corporate Governance Code focuses on: the rights of shareholders, including recommendations on use of electronic means for the purpose of participation in voting and receipt of meeting materials, as well as on protection of dividend rights of shareholders; organising efficient work of the board of directors, i.e. determining the approaches to reasonable and bona fide performance of duties by board members, determining the functions of the board of directors, and organisation of its work and that of its committees; clarification of requirements to board members, including those relating to their independence; recommendations on development of a remuneration system for members of management bodies and key managers of the company, including recommendations relating to various components of such remuneration system (short-term and long- term incentives, severance pay, etc.); recommendations on development of an efficient system of risk management and internal controls; recommendations on additional disclosure of material information about the company and entities controlled thereby and their internal policies; and recommendations on performing material corporate actions (increases in the share capital, acquisitions, listing and delisting of securities, reorganisation, material transactions) which enable one to protect the shareholder rights and ensure the equal treatment of shareholders.', 'This Corporate Governance Code focuses on: the rights of shareholders, including recommendations on use of electronic means for the purpose of participation in voting and receipt of meeting materials, as well as on protection of dividend rights of shareholders; organising efficient work of the board of directors, i.e. determining the approaches to reasonable and bona fide performance of duties by board members, determining the functions of the board of directors, and organisation of its work and that of its committees; clarification of requirements to board members, including those relating to their independence; recommendations on development of a remuneration system for members of management bodies and key managers of the company, including recommendations relating to various components of such remuneration system (short-term and long- term incentives, severance pay, etc.); recommendations on development of an efficient system of risk management and internal controls; recommendations on additional disclosure of material information about the company and entities controlled thereby and their internal policies; and recommendations on performing material corporate actions (increases in the share capital, acquisitions, listing and delisting of securities, reorganisation, material transactions) which enable one to protect the shareholder rights and ensure the equal treatment of shareholders.', 'This Corporate Governance Code focuses on: the rights of shareholders, including recommendations on use of electronic means for the purpose of participation in voting and receipt of meeting materials, as well as on protection of dividend rights of shareholders; organising efficient work of the board of directors, i.e. determining the approaches to reasonable and bona fide performance of duties by board members, determining the functions of the board of directors, and organisation of its work and that of its committees; clarification of requirements to board members, including those relating to their independence; recommendations on development of a remuneration system for members of management bodies and key managers of the company, including recommendations relating to various components of such remuneration system (short-term and long- term incentives, severance pay, etc.); recommendations on development of an efficient system of risk management and internal controls; recommendations on additional disclosure of material information about the company and entities controlled thereby and their internal policies; and recommendations on performing material corporate actions (increases in the share capital, acquisitions, listing and delisting of securities, reorganisation, material transactions) which enable one to protect the shareholder rights and ensure the equal treatment of shareholders.', 'Russia', 'climate', 'in_force', '2014-01-01'::date, 'Russia', 'https://www.carrotsandsticks.org/policies/150_2', ARRAY['russia', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1cb3c301-1fa3-5788-889f-4e1739ddc941', 'Rwanda Official Gazette n° 27bis of 02/ The Capital', 'Official Gazette n° 27bis of 02/07/2012 The Capital Market Corporate Governance Code No 09, 2012', 'The purpose of this code is to ensure that companies are directed and managed at board and management level in a fair and transparent manner. It provides guidance on how the objectives of the company are set and achieved, how risk is monitored and assessed, and how performance is optimized.', 'The purpose of this code is to ensure that companies are directed and managed at board and management level in a fair and transparent manner. It provides guidance on how the objectives of the company are set and achieved, how risk is monitored and assessed, and how performance is optimized.', 'The purpose of this code is to ensure that companies are directed and managed at board and management level in a fair and transparent manner. It provides guidance on how the objectives of the company are set and achieved, how risk is monitored and assessed, and how performance is optimized.', 'Rwanda', 'governance', 'in_force', '2012-01-01'::date, 'Rwanda', 'https://www.carrotsandsticks.org/policies/151_1', ARRAY['guidance_frameworks', 'rwanda', 'other sustainability policy', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8e06143d-4c49-5b21-94f6-3c1057a4fa77', 'Rwanda Guiding Code of Corporate Governance', 'Guiding Code of Corporate Governance, 2009', 'The general aim of the code is to help improve systems and standards of governance in Rwandan companies. This will facilitate in improving efficiency and competitiveness in the business sector. It will also bolster confidence in the capital market and the confidence of the Rwandan society generally, in the way in which business functions.', 'The general aim of the code is to help improve systems and standards of governance in Rwandan companies. This will facilitate in improving efficiency and competitiveness in the business sector. It will also bolster confidence in the capital market and the confidence of the Rwandan society generally, in the way in which business functions.', 'The general aim of the code is to help improve systems and standards of governance in Rwandan companies. This will facilitate in improving efficiency and competitiveness in the business sector. It will also bolster confidence in the capital market and the confidence of the Rwandan society generally, in the way in which business functions.', 'Rwanda', 'governance', 'in_force', '2009-01-01'::date, 'Rwanda', 'https://www.carrotsandsticks.org/policies/151_2', ARRAY['rwanda', 'other sustainability policy', 'mandatory', 'sdg16', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0f2221ab-e70f-5b92-ad54-f33eb822fd02', 'San Marino Council Decree 26 September 2025 n.119', 'Council Decree 26 September 2025 n.119 - Ratification of the Multilateral Convention to Facilitate the Implementation of the Second Pillar Tax Requirement Rule (STTR)', 'San Marino''s Council Decree ratifies the Multilateral Convention to Implement the Second Pillar Tax Requirement Rule (STTR). It aims to address tax challenges from digital economy growth, facilitating consistent tax rule application in existing agreements to avoid double taxation, benefiting participating states and developing countries.', 'San Marino''s Council Decree ratifies the Multilateral Convention to Implement the Second Pillar Tax Requirement Rule (STTR). It aims to address tax challenges from digital economy growth, facilitating consistent tax rule application in existing agreements to avoid double taxation, benefiting participating states and developing countries.', 'San Marino''s Council Decree ratifies the Multilateral Convention to Implement the Second Pillar Tax Requirement Rule (STTR). It aims to address tax challenges from digital economy growth, facilitating consistent tax rule application in existing agreements to avoid double taxation, benefiting participating states and developing countries.', 'San Marino', 'governance', 'in_force', '2025-01-01'::date, 'San Marino', 'https://www.carrotsandsticks.org/policies/202_2', ARRAY['san marino', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b030d656-0402-5a3a-9adc-7212e58d2303', 'San Marino Law of 9 May 2016 Freedom of', 'Law No. 59 of 9 May 2016 Freedom of association and union activity in workplaces, collective bargaining and right to strike', 'Law No. 59 of 9 May 2016 in San Marino aims to regulate freedom of association, union activities, collective bargaining, and the right to strike in workplaces. It outlines rules for union registration, financing, representation, collective agreements, and judicial protection of union rights, applicable to both private and public sectors.', 'Law No. 59 of 9 May 2016 in San Marino aims to regulate freedom of association, union activities, collective bargaining, and the right to strike in workplaces. It outlines rules for union registration, financing, representation, collective agreements, and judicial protection of union rights, applicable to both private and public sectors.', 'Law No. 59 of 9 May 2016 in San Marino aims to regulate freedom of association, union activities, collective bargaining, and the right to strike in workplaces. It outlines rules for union registration, financing, representation, collective agreements, and judicial protection of union rights, applicable to both private and public sectors.', 'San Marino', 'governance', 'in_force', '2016-01-01'::date, 'San Marino', 'https://www.carrotsandsticks.org/policies/202_3', ARRAY['san marino', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ae10aa5a-c823-52c0-87c8-98a5503e581e', 'San Marino 2012 Environmental Code', '2012 Environmental Code', 'The 2012 Environmental Code of San Marino aims to enhance human life quality by safeguarding the environment and natural resources. It covers waste management, asbestos risk prevention, water protection, air quality, and noise pollution regulations. Targeted at government agencies, experts, and stakeholders involved in environmental protection.', 'The 2012 Environmental Code of San Marino aims to enhance human life quality by safeguarding the environment and natural resources. It covers waste management, asbestos risk prevention, water protection, air quality, and noise pollution regulations. Targeted at government agencies, experts, and stakeholders involved in environmental protection.', 'The 2012 Environmental Code of San Marino aims to enhance human life quality by safeguarding the environment and natural resources. It covers waste management, asbestos risk prevention, water protection, air quality, and noise pollution regulations. Targeted at government agencies, experts, and stakeholders involved in environmental protection.', 'San Marino', 'circularity', 'in_force', '2012-01-01'::date, 'San Marino', 'https://www.carrotsandsticks.org/policies/202_1', ARRAY['san marino', 'regulations', 'mandatory', 'sdg6', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4784142b-447a-51dc-a0b7-099994e42041', 'Saudi Arabia ESG Disclosure Guidelines', 'ESG Disclosure Guidelines', 'The six Principles for Responsible Investment outlined in this document are a voluntary and aspirational set of investment principles that offer a menu of possible actions for incorporating ESG issues into investment practice.', 'The six Principles for Responsible Investment outlined in this document are a voluntary and aspirational set of investment principles that offer a menu of possible actions for incorporating ESG issues into investment practice.', 'The six Principles for Responsible Investment outlined in this document are a voluntary and aspirational set of investment principles that offer a menu of possible actions for incorporating ESG issues into investment practice.', 'Saudi Arabia', 'climate', 'in_force', '2021-01-01'::date, 'Saudi Arabia', 'https://www.carrotsandsticks.org/policies/155_2', ARRAY['guidance_frameworks', 'sdg13', 'sdg16', 'saudi arabia', 'sdg12', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e8936544-9f87-5bab-a78f-c3afc67fcb25', 'Saudi Arabia Corporate Governance Regulations in', 'Corporate Governance Regulations in the Kingdom of Saudi Arabia, 2017', 'These Regulations state the rules and standards that regulate the management of the companies to ensure its compliance with the best governance practices that ensure the protection of shareholder''s rights as well as the rights of Stakeholders.', 'These Regulations state the rules and standards that regulate the management of the companies to ensure its compliance with the best governance practices that ensure the protection of shareholder''s rights as well as the rights of Stakeholders.', 'These Regulations state the rules and standards that regulate the management of the companies to ensure its compliance with the best governance practices that ensure the protection of shareholder''s rights as well as the rights of Stakeholders.', 'Saudi Arabia', 'governance', 'in_force', '2017-01-01'::date, 'Saudi Arabia', 'https://www.carrotsandsticks.org/policies/155_1', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'saudi arabia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c59780dd-c445-5b82-8200-f66e8c1e671f', 'Saudi Arabia Corporate Governance Regulations in', 'Corporate Governance Regulations in the Kingdom of Saudi Arabia, 2006', 'These Regulations include the rules and standards that regulate the management of joint stock companies listed in the Exchange to ensure their compliance with the best governance practices that would ensure the protection of shareholders’ rights as well as the rights of stakeholders.', 'These Regulations include the rules and standards that regulate the management of joint stock companies listed in the Exchange to ensure their compliance with the best governance practices that would ensure the protection of shareholders’ rights as well as the rights of stakeholders.', 'These Regulations include the rules and standards that regulate the management of joint stock companies listed in the Exchange to ensure their compliance with the best governance practices that would ensure the protection of shareholders’ rights as well as the rights of stakeholders.', 'Saudi Arabia', 'governance', 'in_force', '2006-01-01'::date, 'Saudi Arabia', 'https://www.carrotsandsticks.org/policies/155_3', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'saudi arabia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1ca71a5d-1081-5dd0-86c4-bb1523c31165', 'SBTi draft Corporate Net-Zero Standard Version 2.0', 'SBTi draft Corporate Net-Zero Standard Version 2.0,', 'This policy was published in 2025 by Science Based Targets (SBTi). It addresses sustainability and corporate responsibility requirements.', 'This policy was published in 2025 by Science Based Targets (SBTi). It addresses sustainability and corporate responsibility requirements.', 'This policy was published in 2025 by Science Based Targets (SBTi). It addresses sustainability and corporate responsibility requirements.', 'SBTi', 'climate', 'in_force', '2025-01-01'::date, 'Science Based Targets (SBTi)', 'https://www.carrotsandsticks.org/policies/324_3', ARRAY['voluntary_frameworks', 'sdg13', 'voluntary', 'sbti']::text[]) ON CONFLICT (id) DO NOTHING;
