INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('84054dea-ab44-5231-8877-3ce9ed42dac7', 'SBTi Criteria and Recommendations', 'SBTi Criteria and Recommendations, 2020', 'All of the criteria listed in this instrument must be met in order for target(s) to be recognized by the Science Based Targets initiative (SBTi). This criteria version 4.1 will be in effect as of July 15th, 2020. All submissions received by the SBTi prior to July 15th, 2020 can be assessed against the criteria version 4.0 or 4.1. Criteria, recommendations and best practices denoted with an asterisk (*) are refinements and additions to/clarifications of pre-existing criteria and recommendations.', 'All of the criteria listed in this instrument must be met in order for target(s) to be recognized by the Science Based Targets initiative (SBTi). This criteria version 4.1 will be in effect as of July 15th, 2020. All submissions received by the SBTi prior to July 15th, 2020 can be assessed against the criteria version 4.0 or 4.1. Criteria, recommendations and best practices denoted with an asterisk (*) are refinements and additions to/clarifications of pre-existing criteria and recommendations.', 'All of the criteria listed in this instrument must be met in order for target(s) to be recognized by the Science Based Targets initiative (SBTi). This criteria version 4.1 will be in effect as of July 15th, 2020. All submissions received by the SBTi prior to July 15th, 2020 can be assessed against the criteria version 4.0 or 4.1. Criteria, recommendations and best practices denoted with an asterisk (*) are refinements and additions to/clarifications of pre-existing criteria and recommendations.', 'SBTi', 'governance', 'in_force', '2020-01-01'::date, 'Science Based Targets (SBTi)', 'https://www.carrotsandsticks.org/policies/324_2', ARRAY['guidance_frameworks', 'voluntary', 'sbti', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3c8e5bbe-29be-5c55-b9b7-d32731c773b1', 'SBTi Foundations of Science-based Target Setting', 'Foundations of Science-based Target Setting, 2019', 'This document describes the SBTi’s framework for developing target-setting methods that are in line with science and for evaluating emissions scenarios associated with these methods. In the spirit of transparency and recognizing the value of sharing a full description of the SBTi’s approach, this document includes a substantial amount of analytical detail and specifies how a diverse body of research is reflected by methods endorsed by the SBTi. The intended audience of this document includes researchers, sustainability professional who are involved with sector-specific development, and readers who wish to understand the technical underpinnings of SBTi methods. For practical guidance on setting an SBT, please refer to the Science-based Target Setting Manual.', 'This document describes the SBTi’s framework for developing target-setting methods that are in line with science and for evaluating emissions scenarios associated with these methods. In the spirit of transparency and recognizing the value of sharing a full description of the SBTi’s approach, this document includes a substantial amount of analytical detail and specifies how a diverse body of research is reflected by methods endorsed by the SBTi. The intended audience of this document includes researchers, sustainability professional who are involved with sector-specific development, and readers who wish to understand the technical underpinnings of SBTi methods. For practical guidance on setting an SBT, please refer to the Science-based Target Setting Manual.', 'This document describes the SBTi’s framework for developing target-setting methods that are in line with science and for evaluating emissions scenarios associated with these methods. In the spirit of transparency and recognizing the value of sharing a full description of the SBTi’s approach, this document includes a substantial amount of analytical detail and specifies how a diverse body of research is reflected by methods endorsed by the SBTi. The intended audience of this document includes researchers, sustainability professional who are involved with sector-specific development, and readers who wish to understand the technical underpinnings of SBTi methods. For practical guidance on setting an SBT, please refer to the Science-based Target Setting Manual.', 'SBTi', 'climate', 'in_force', '2019-01-01'::date, 'Science Based Targets (SBTi)', 'https://www.carrotsandsticks.org/policies/324_1', ARRAY['sdg13', 'sdg14', 'sbti', 'other sustainability policy', 'regulations', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('fc0df241-89bb-510f-b7e6-702dc2d11301', 'Serbia Law on Taxes on Greenhouse Gas Emissions', 'No. 109/2025 Law on Taxes on Greenhouse Gas Emissions', 'The No. 109/2025 Law on Taxes on Greenhouse Gas Emissions in Serbia introduces a tax on greenhouse gas emissions for businesses engaged in specified activities. It outlines tax calculations, reporting requirements, and incentives for reducing emissions, primarily targeting entities emitting greenhouse gases.', 'The No. 109/2025 Law on Taxes on Greenhouse Gas Emissions in Serbia introduces a tax on greenhouse gas emissions for businesses engaged in specified activities. It outlines tax calculations, reporting requirements, and incentives for reducing emissions, primarily targeting entities emitting greenhouse gases.', 'The No. 109/2025 Law on Taxes on Greenhouse Gas Emissions in Serbia introduces a tax on greenhouse gas emissions for businesses engaged in specified activities. It outlines tax calculations, reporting requirements, and incentives for reducing emissions, primarily targeting entities emitting greenhouse gases.', 'Serbia', 'climate', 'in_force', '2025-01-01'::date, 'Serbia', 'https://www.carrotsandsticks.org/policies/157_7', ARRAY['serbia', 'mandatory', 'sdg13', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f2830748-2eb7-52d6-9803-18ca6c185103', 'Serbia Law on the tax on the import', 'No. 109/2025 Law on the tax on the import of carbon intensive products', 'Serbia''s Law No. 109/2025 imposes a tax on the import of carbon-intensive products, targeting specific categories like iron, steel, cement, fertilizer, and aluminum. The tax amount is based on CO2 emissions per ton imported. The law aims to reduce carbon emissions and encourage environmentally friendly practices among importers.', 'Serbia''s Law No. 109/2025 imposes a tax on the import of carbon-intensive products, targeting specific categories like iron, steel, cement, fertilizer, and aluminum. The tax amount is based on CO2 emissions per ton imported. The law aims to reduce carbon emissions and encourage environmentally friendly practices among importers.', 'Serbia''s Law No. 109/2025 imposes a tax on the import of carbon-intensive products, targeting specific categories like iron, steel, cement, fertilizer, and aluminum. The tax amount is based on CO2 emissions per ton imported. The law aims to reduce carbon emissions and encourage environmentally friendly practices among importers.', 'Serbia', 'climate', 'in_force', '2025-01-01'::date, 'Serbia', 'https://www.carrotsandsticks.org/policies/157_8', ARRAY['serbia', 'mandatory', 'sdg13', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e38ffab4-ed15-5b5a-aa1c-7c3ec8e91176', 'Serbia Law on Environmental Impact Assessment', 'The Law on Environmental Impact Assessment No. 94/2024', 'The Law on Environmental Impact Assessment No. 94/2024 in Serbia outlines procedures for assessing environmental impacts of significant projects, involving stakeholders, cross-border consultations, and monitoring. It excludes projects for immediate danger prevention, defense, and health and property protection. Key terms and responsibilities are defined for project assessment and approval.', 'The Law on Environmental Impact Assessment No. 94/2024 in Serbia outlines procedures for assessing environmental impacts of significant projects, involving stakeholders, cross-border consultations, and monitoring. It excludes projects for immediate danger prevention, defense, and health and property protection. Key terms and responsibilities are defined for project assessment and approval.', 'The Law on Environmental Impact Assessment No. 94/2024 in Serbia outlines procedures for assessing environmental impacts of significant projects, involving stakeholders, cross-border consultations, and monitoring. It excludes projects for immediate danger prevention, defense, and health and property protection. Key terms and responsibilities are defined for project assessment and approval.', 'Serbia', 'governance', 'in_force', '2024-01-01'::date, 'Serbia', 'https://www.carrotsandsticks.org/policies/157_4', ARRAY['serbia', 'mandatory', 'sdg3', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('65ddd188-bb7b-5f85-8438-1e9b400c9c25', 'Serbia Amendments to the Law on Energy', 'Law on Amendments to the Law on Energy No. 94/2024', 'The Law on Amendments to the Law on Energy in Serbia, dated 2024, introduces changes related to nuclear energy development and defines terms for energy regulation. It targets energy stakeholders, clarifying roles, responsibilities, and market mechanisms for efficient energy management and trade.', 'The Law on Amendments to the Law on Energy in Serbia, dated 2024, introduces changes related to nuclear energy development and defines terms for energy regulation. It targets energy stakeholders, clarifying roles, responsibilities, and market mechanisms for efficient energy management and trade.', 'The Law on Amendments to the Law on Energy in Serbia, dated 2024, introduces changes related to nuclear energy development and defines terms for energy regulation. It targets energy stakeholders, clarifying roles, responsibilities, and market mechanisms for efficient energy management and trade.', 'Serbia', 'climate', 'in_force', '2024-01-01'::date, 'Serbia', 'https://www.carrotsandsticks.org/policies/157_5', ARRAY['sdg7', 'serbia', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d7b50c82-af07-5a6d-a290-bf766ce3ef38', 'Serbia Law on the Use of Renewable Energy Sources', 'No. 94/2024 Law on the Use of Renewable Energy Sources:', 'The No. 94/2024 Law on the Use of Renewable Energy Sources in Serbia regulates the utilization of renewable energy, sets energy goals, outlines incentive systems, and promotes environmental protection, innovation, and energy independence. It targets entities involved in energy production, distribution, and consumption within the country.', 'The No. 94/2024 Law on the Use of Renewable Energy Sources in Serbia regulates the utilization of renewable energy, sets energy goals, outlines incentive systems, and promotes environmental protection, innovation, and energy independence. It targets entities involved in energy production, distribution, and consumption within the country.', 'The No. 94/2024 Law on the Use of Renewable Energy Sources in Serbia regulates the utilization of renewable energy, sets energy goals, outlines incentive systems, and promotes environmental protection, innovation, and energy independence. It targets entities involved in energy production, distribution, and consumption within the country.', 'Serbia', 'climate', 'in_force', '2024-01-01'::date, 'Serbia', 'https://www.carrotsandsticks.org/policies/157_9', ARRAY['regulations', 'sdg7', 'mandatory', 'serbia', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c026f4d4-35e4-591a-b471-a3e9cace48a3', 'Serbia Accounting 2021 ( Nos. and ))', 'Law on Accounting 2021 ( Nos. 62/2013 and 30/2018))', 'The Law on Accounting in Serbia was updated in 2021, building on previous versions from 2013 and 2018. The main aim of the updated law is to harmonize the accounting system in Serbia with international standards, specifically the International Financial Reporting Standards (IFRS) and the European Union''s Accounting Directive. The updated law outlines the requirements for financial statements, including balance sheets, profit and loss statements, and cash flow statements, as well as rules for recording, classifying, and disclosing financial information. It also establishes new rules for auditing financial statements, including the certification of auditors and the procedures for conducting audits. The law requires companies to adopt the IFRS for financial reporting, with some exceptions for small and medium-sized enterprises (SMEs). Additionally, the law outlines specific requirements for the preparation and disclosure of financial statements for listed companies and companies that issue bonds or other securities.', 'The Law on Accounting in Serbia was updated in 2021, building on previous versions from 2013 and 2018. The main aim of the updated law is to harmonize the accounting system in Serbia with international standards, specifically the International Financial Reporting Standards (IFRS) and the European Union''s Accounting Directive. The updated law outlines the requirements for financial statements, including balance sheets, profit and loss statements, and cash flow statements, as well as rules for recording, classifying, and disclosing financial information. It also establishes new rules for auditing financial statements, including the certification of auditors and the procedures for conducting audits. The law requires companies to adopt the IFRS for financial reporting, with some exceptions for small and medium-sized enterprises (SMEs). Additionally, the law outlines specific requirements for the preparation and disclosure of financial statements for listed companies and companies that issue bonds or other securities.', 'The Law on Accounting in Serbia was updated in 2021, building on previous versions from 2013 and 2018. The main aim of the updated law is to harmonize the accounting system in Serbia with international standards, specifically the International Financial Reporting Standards (IFRS) and the European Union''s Accounting Directive. The updated law outlines the requirements for financial statements, including balance sheets, profit and loss statements, and cash flow statements, as well as rules for recording, classifying, and disclosing financial information. It also establishes new rules for auditing financial statements, including the certification of auditors and the procedures for conducting audits. The law requires companies to adopt the IFRS for financial reporting, with some exceptions for small and medium-sized enterprises (SMEs). Additionally, the law outlines specific requirements for the preparation and disclosure of financial statements for listed companies and companies that issue bonds or other securities.', 'Serbia', 'climate', 'in_force', '2021-01-01'::date, 'Serbia', 'https://www.carrotsandsticks.org/policies/157_2', ARRAY['serbia', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b6bb17ff-8f88-5fbd-9ea4-feaeabd54665', 'Serbia Gender Equality', 'Law on Gender Equality 2021', 'In 2021, Serbia enacted a new Law on Gender Equality, aimed at promoting gender equality and preventing discrimination based on gender in all areas of society. The law replaces the previous Law on Gender Equality from 2009 and aims to align with international standards, including the United Nations Convention on the Elimination of All Forms of Discrimination Against Women. The law establishes a framework for promoting gender equality, including the establishment of gender equality bodies and the development of national action plans on gender equality. It also prohibits discrimination on the basis of gender in employment, education, healthcare, and other areas, and requires public institutions to promote gender equality in their policies and practices. The law recognizes the importance of eliminating gender stereotypes and promoting women''s empowerment, including through measures such as affirmative action and support for women''s entrepreneurship. It also provides for measures to protect women from gender-based violence and harassment, including through the establishment of support services and the criminalization of certain forms of violence against women.', 'In 2021, Serbia enacted a new Law on Gender Equality, aimed at promoting gender equality and preventing discrimination based on gender in all areas of society. The law replaces the previous Law on Gender Equality from 2009 and aims to align with international standards, including the United Nations Convention on the Elimination of All Forms of Discrimination Against Women. The law establishes a framework for promoting gender equality, including the establishment of gender equality bodies and the development of national action plans on gender equality. It also prohibits discrimination on the basis of gender in employment, education, healthcare, and other areas, and requires public institutions to promote gender equality in their policies and practices. The law recognizes the importance of eliminating gender stereotypes and promoting women''s empowerment, including through measures such as affirmative action and support for women''s entrepreneurship. It also provides for measures to protect women from gender-based violence and harassment, including through the establishment of support services and the criminalization of certain forms of violence against women.', 'In 2021, Serbia enacted a new Law on Gender Equality, aimed at promoting gender equality and preventing discrimination based on gender in all areas of society. The law replaces the previous Law on Gender Equality from 2009 and aims to align with international standards, including the United Nations Convention on the Elimination of All Forms of Discrimination Against Women. The law establishes a framework for promoting gender equality, including the establishment of gender equality bodies and the development of national action plans on gender equality. It also prohibits discrimination on the basis of gender in employment, education, healthcare, and other areas, and requires public institutions to promote gender equality in their policies and practices. The law recognizes the importance of eliminating gender stereotypes and promoting women''s empowerment, including through measures such as affirmative action and support for women''s entrepreneurship. It also provides for measures to protect women from gender-based violence and harassment, including through the establishment of support services and the criminalization of certain forms of violence against women.', 'Serbia', 'climate', 'in_force', '2021-01-01'::date, 'Serbia', 'https://www.carrotsandsticks.org/policies/157_3', ARRAY['sdg4', 'sdg8', 'sdg10', 'regulations', 'mandatory', 'sdg5', 'serbia', 'disclosure', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('da752afa-f9a5-5984-95e3-d37a3c286850', 'Serbia climate', 'Law about climate No. 26/2021', 'Serbia''s Law about climate No. 26/2021 establishes a system to limit greenhouse gas emissions, adapt to climate change, and enhance low-carbon development strategies. It aims to reduce emissions cost-effectively, comply with international agreements, and involve stakeholders in monitoring and reporting efforts. Target audience includes operators, aviation entities, and organizations implementing climate policies.', 'Serbia''s Law about climate No. 26/2021 establishes a system to limit greenhouse gas emissions, adapt to climate change, and enhance low-carbon development strategies. It aims to reduce emissions cost-effectively, comply with international agreements, and involve stakeholders in monitoring and reporting efforts. Target audience includes operators, aviation entities, and organizations implementing climate policies.', 'Serbia''s Law about climate No. 26/2021 establishes a system to limit greenhouse gas emissions, adapt to climate change, and enhance low-carbon development strategies. It aims to reduce emissions cost-effectively, comply with international agreements, and involve stakeholders in monitoring and reporting efforts. Target audience includes operators, aviation entities, and organizations implementing climate policies.', 'Serbia', 'climate', 'in_force', '2021-01-01'::date, 'Serbia', 'https://www.carrotsandsticks.org/policies/157_6', ARRAY['serbia', 'mandatory', 'sdg13', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('fa2d1131-12ce-5e23-a530-714022cecdfe', 'Serbia Corporate Governance Code of the Belgrade Stock Exchange', 'Corporate Governance Code of the Belgrade Stock Exchange', 'This Code has been developed in the regulatory framework of the Law on Business Companies, Law on Securities Market and other financial instruments and by­laws of the Securities Commission of the Republic of Serbia. When drafting the Code, the intention was to avoid to the greatest possible extent the repeating of imperative provisions of the afore­ said regulations covering good corporate governance rules, and to focus on the further upgrading of corporative relations through the implementation of internationally accepted principles and best practice of the corporate governance.', 'This Code has been developed in the regulatory framework of the Law on Business Companies, Law on Securities Market and other financial instruments and by­laws of the Securities Commission of the Republic of Serbia. When drafting the Code, the intention was to avoid to the greatest possible extent the repeating of imperative provisions of the afore­ said regulations covering good corporate governance rules, and to focus on the further upgrading of corporative relations through the implementation of internationally accepted principles and best practice of the corporate governance.', 'This Code has been developed in the regulatory framework of the Law on Business Companies, Law on Securities Market and other financial instruments and by­laws of the Securities Commission of the Republic of Serbia. When drafting the Code, the intention was to avoid to the greatest possible extent the repeating of imperative provisions of the afore­ said regulations covering good corporate governance rules, and to focus on the further upgrading of corporative relations through the implementation of internationally accepted principles and best practice of the corporate governance.', 'Serbia', 'governance', 'in_force', '2008-01-01'::date, 'Serbia', 'https://www.carrotsandsticks.org/policies/157_1', ARRAY['regulations', 'mandatory', 'sdg16', 'serbia', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('29566032-eb73-5992-afb1-18344e7fa502', 'Sierra Leone Mines and Minerals Development Act', 'Mines and Minerals Development Act, 2022', 'Replacing the 2009 Act, Sierra Leone''s 2022 Mines and Minerals Development Act revamps the industry. Mandatory for all mineral activity, it sets new rules for exploration, mining, trade, and exports. From onshore resources to deep sea mining, it covers all categories of minerals. Companies must comply with licensing, reporting, environmental, and social responsibility requirements, or face penalties like fines and license revocation. This robust framework aims for responsible and sustainable mineral resource development in Sierra Leone.', 'Replacing the 2009 Act, Sierra Leone''s 2022 Mines and Minerals Development Act revamps the industry. Mandatory for all mineral activity, it sets new rules for exploration, mining, trade, and exports. From onshore resources to deep sea mining, it covers all categories of minerals. Companies must comply with licensing, reporting, environmental, and social responsibility requirements, or face penalties like fines and license revocation. This robust framework aims for responsible and sustainable mineral resource development in Sierra Leone.', 'Replacing the 2009 Act, Sierra Leone''s 2022 Mines and Minerals Development Act revamps the industry. Mandatory for all mineral activity, it sets new rules for exploration, mining, trade, and exports. From onshore resources to deep sea mining, it covers all categories of minerals. Companies must comply with licensing, reporting, environmental, and social responsibility requirements, or face penalties like fines and license revocation. This robust framework aims for responsible and sustainable mineral resource development in Sierra Leone.', 'Sierra Leone', 'climate', 'in_force', '2022-01-01'::date, 'Sierra Leone', 'https://www.carrotsandsticks.org/policies/159_3', ARRAY['sdg14', 'regulations', 'mandatory', 'disclosure', 'sierra leone', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3fd92b9e-1889-5bc7-9a61-b90d56556368', 'Sierra Leone National Corporate Governance Code', 'National Corporate Governance Code, 2018', 'The Corporate Governance Code of Sierra Leone provides guidance to Boards, Management and Organizations operating in Sierra Leone across a range of sectors.', 'The Corporate Governance Code of Sierra Leone provides guidance to Boards, Management and Organizations operating in Sierra Leone across a range of sectors.', 'The Corporate Governance Code of Sierra Leone provides guidance to Boards, Management and Organizations operating in Sierra Leone across a range of sectors.', 'Sierra Leone', 'governance', 'in_force', '2018-01-01'::date, 'Sierra Leone', 'https://www.carrotsandsticks.org/policies/159_1', ARRAY['guidance_frameworks', 'mandatory', 'sdg16', 'disclosure', 'sierra leone']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ecf9f292-f86b-5b77-9acc-989fc1178052', 'Draft Corporate Governance Code for Sierra Leone', 'Draft Corporate Governance Code for Sierra Leone, 2017', 'This is the Draft version of the Corporate Governance Code of Sierra Leone which will provide guidance to Boards, Management and Organizations operating in Sierra Leone across a range of sectors.', 'This is the Draft version of the Corporate Governance Code of Sierra Leone which will provide guidance to Boards, Management and Organizations operating in Sierra Leone across a range of sectors.', 'This is the Draft version of the Corporate Governance Code of Sierra Leone which will provide guidance to Boards, Management and Organizations operating in Sierra Leone across a range of sectors.', 'Sierra Leone', 'governance', 'in_force', '2017-01-01'::date, 'Sierra Leone', 'https://www.carrotsandsticks.org/policies/159_2', ARRAY['guidance_frameworks', 'mandatory', 'sdg16', 'disclosure', 'sierra leone']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('101dbc37-1d44-563c-ab79-814b1703823f', 'Singapore-Asia Taxonomy for Sustainable Finance 2023 Edition', 'Singapore-Asia Taxonomy for Sustainable Finance 2023 Edition', 'Unveiled in December 2023, Singapore''s multi-sector "Taxonomy" defines green and transition activities across eight key industries (energy, transport, etc.). Aimed at reducing "greenwashing," it guides financiers and policymakers towards sustainable investments aligned with Asia''s needs. Its detailed technical criteria offer clarity on qualifying activities, enabling responsible financing and accelerating the region''s transition to a low-carbon future.', 'Unveiled in December 2023, Singapore''s multi-sector "Taxonomy" defines green and transition activities across eight key industries (energy, transport, etc.). Aimed at reducing "greenwashing," it guides financiers and policymakers towards sustainable investments aligned with Asia''s needs. Its detailed technical criteria offer clarity on qualifying activities, enabling responsible financing and accelerating the region''s transition to a low-carbon future.', 'Unveiled in December 2023, Singapore''s multi-sector "Taxonomy" defines green and transition activities across eight key industries (energy, transport, etc.). Aimed at reducing "greenwashing," it guides financiers and policymakers towards sustainable investments aligned with Asia''s needs. Its detailed technical criteria offer clarity on qualifying activities, enabling responsible financing and accelerating the region''s transition to a low-carbon future.', 'Singapore', 'climate', 'in_force', '2023-01-01'::date, 'Singapore', 'https://www.carrotsandsticks.org/policies/160_17', ARRAY['sdg13', 'sdg7', 'sdg11', 'mandatory', 'singapore', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b9eca05d-e3ab-5c4c-9abe-368970072a96', 'Singapore Enhancements to Sustainability Reporting Regime and Board Diversity', 'Enhancements to Sustainability Reporting Regime and Board Diversity Disclosures', 'The Enhancements to Sustainability Reporting Regime and Board Diversity Disclosures, part of the SGX Mainboard Rules Amendments, introduce stricter reporting obligations for listed issuers in Singapore. These changes emphasize the importance of Environmental, Social, and Governance (ESG) factors and board diversity in corporate governance. The key amendments include: (1) Sustainability Reporting: Mandatory annual sustainability reports that include material ESG factors, climate-related disclosures (aligned with TCFD recommendations), policies, targets, and a board statement. Issuers must explain any exclusion of required reporting components and ensure internal or external assurance of sustainability reports.
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7ad59671-8abc-53f6-8238-e2fc77884e3a', 'Singapore Starting with a common set of core ESG', 'Starting with a common set of core ESG metrics, 2021', 'The SGX has proposed a list of core ESG (Environmental, Social, and Governance) metrics to assist issuers in providing and investors in accessing aligned ESG data. The Core ESG Metrics list consists of quantitative metrics that are relevant to most sectors and mapped against globally-accepted sustainability reporting frameworks. It is intended to provide guidance for issuers to disclose a standardised set of ESG metrics, creating better alignment between users and reporters of ESG information. The list has garnered strong support from respondents and is endorsed by institutional investors. SGX recommends issuers use the Core ESG Metrics as a starting point for reporting to facilitate consistency and comparability of ESG data disclosures, while still conducting a materiality assessment to ensure the relevance and completeness of their reported metrics. The list will be reviewed and revised periodically to keep in line with the evolution of international reporting standards. The list of Core ESG Metrics is included in the proposal.', 'The SGX has proposed a list of core ESG (Environmental, Social, and Governance) metrics to assist issuers in providing and investors in accessing aligned ESG data. The Core ESG Metrics list consists of quantitative metrics that are relevant to most sectors and mapped against globally-accepted sustainability reporting frameworks. It is intended to provide guidance for issuers to disclose a standardised set of ESG metrics, creating better alignment between users and reporters of ESG information. The list has garnered strong support from respondents and is endorsed by institutional investors. SGX recommends issuers use the Core ESG Metrics as a starting point for reporting to facilitate consistency and comparability of ESG data disclosures, while still conducting a materiality assessment to ensure the relevance and completeness of their reported metrics. The list will be reviewed and revised periodically to keep in line with the evolution of international reporting standards. The list of Core ESG Metrics is included in the proposal.', 'The SGX has proposed a list of core ESG (Environmental, Social, and Governance) metrics to assist issuers in providing and investors in accessing aligned ESG data. The Core ESG Metrics list consists of quantitative metrics that are relevant to most sectors and mapped against globally-accepted sustainability reporting frameworks. It is intended to provide guidance for issuers to disclose a standardised set of ESG metrics, creating better alignment between users and reporters of ESG information. The list has garnered strong support from respondents and is endorsed by institutional investors. SGX recommends issuers use the Core ESG Metrics as a starting point for reporting to facilitate consistency and comparability of ESG data disclosures, while still conducting a materiality assessment to ensure the relevance and completeness of their reported metrics. The list will be reviewed and revised periodically to keep in line with the evolution of international reporting standards. The list of Core ESG Metrics is included in the proposal.', 'Singapore', 'climate', 'in_force', '2021-01-01'::date, 'Singapore', 'https://www.carrotsandsticks.org/policies/160_16', ARRAY['mandatory', 'singapore', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7ac17bc0-d8e3-5820-a0a3-2030d56da289', 'Singapore Environmental Risk Management (Asset Managers)', 'Guidelines on Environmental Risk Management (Asset Managers), 2020', 'The Guidelines aim to enhance the resilience of funds (including REITs) and segregated mandates (hereinafter collectively referred to as “funds/mandates”) that are managed by asset managers, by setting out sound environmental risk management practices that asset managers can adopt.', 'The Guidelines aim to enhance the resilience of funds (including REITs) and segregated mandates (hereinafter collectively referred to as “funds/mandates”) that are managed by asset managers, by setting out sound environmental risk management practices that asset managers can adopt.', 'The Guidelines aim to enhance the resilience of funds (including REITs) and segregated mandates (hereinafter collectively referred to as “funds/mandates”) that are managed by asset managers, by setting out sound environmental risk management practices that asset managers can adopt.', 'Singapore', 'governance', 'in_force', '2020-01-01'::date, 'Singapore', 'https://www.carrotsandsticks.org/policies/160_12', ARRAY['guidance_frameworks', 'voluntary', 'singapore', 'other sustainability policy']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0cc08f09-0f8e-51dd-b5a9-c932ef3dc831', 'Singapore Environmental Risk Management (Banks)', 'Guidelines on Environmental Risk Management (Banks), 2020', 'These Guidelines aim to enhance the banking sector’s resilience to and management of environmental risk through setting out sound risk management practices.', 'These Guidelines aim to enhance the banking sector’s resilience to and management of environmental risk through setting out sound risk management practices.', 'These Guidelines aim to enhance the banking sector’s resilience to and management of environmental risk through setting out sound risk management practices.', 'Singapore', 'governance', 'in_force', '2020-01-01'::date, 'Singapore', 'https://www.carrotsandsticks.org/policies/160_13', ARRAY['guidance_frameworks', 'voluntary', 'singapore', 'other sustainability policy']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('327688ba-91a1-527a-ae17-54a1395d7529', 'Singapore Environmental Risk Management (Insurers)', 'Guidelines on Environmental Risk Management (Insurers), 2020', 'These Guidelines aim to enhance the insurance sector’s resilience to and management of environmental risk through setting out sound risk management practices.', 'These Guidelines aim to enhance the insurance sector’s resilience to and management of environmental risk through setting out sound risk management practices.', 'These Guidelines aim to enhance the insurance sector’s resilience to and management of environmental risk through setting out sound risk management practices.', 'Singapore', 'governance', 'in_force', '2020-01-01'::date, 'Singapore', 'https://www.carrotsandsticks.org/policies/160_14', ARRAY['guidance_frameworks', 'voluntary', 'singapore', 'other sustainability policy']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5c737ea1-ca13-5103-ba1f-cf29c8970b58', 'Singapore Carbon Pricing Act', 'Carbon Pricing Act', 'The Carbon Pricing Act, 2018, implemented in Singapore, establishes a comprehensive framework for carbon taxation and greenhouse gas (GHG) emissions reporting. The legislation applies to industrial facilities emitting GHGs at or above prescribed thresholds, requiring them to register as taxable or reportable facilities. Taxable facilities are subject to a carbon tax based on the amount of emissions, while both categories are mandated to submit annual emissions reports verified by accredited third-party auditors.
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3bff42a5-90e6-50ca-b8d9-f04438bda233', 'Singapore Sustainability Reporting Guide', 'Sustainability Reporting Guide, 2018', 'This Sustainability Reporting Guide (the “Guide”) provides guidance on the expected structure and contents and the preparation of the sustainability report.', 'This Sustainability Reporting Guide (the “Guide”) provides guidance on the expected structure and contents and the preparation of the sustainability report.', 'This Sustainability Reporting Guide (the “Guide”) provides guidance on the expected structure and contents and the preparation of the sustainability report.', 'Singapore', 'climate', 'in_force', '2018-01-01'::date, 'Singapore', 'https://www.carrotsandsticks.org/policies/160_6', ARRAY['sdg13', 'mandatory', 'singapore', 'sdg16', 'mandatory_regulations', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('81b10a00-a807-5ad3-97bf-845d09586f0e', 'Singapore SGX-ST Listing Rules Practice Note 7.6 Amendments', 'SGX-ST Listing Rules Practice Note 7.6 Amendments to Sustainability Reporting Guide', 'This document is a Practice Note on Sustainbility reporting, published on and effective from the 20th June 2015.', 'This document is a Practice Note on Sustainbility reporting, published on and effective from the 20th June 2015.', 'This document is a Practice Note on Sustainbility reporting, published on and effective from the 20th June 2015.', 'Singapore', 'climate', 'in_force', '2016-01-01'::date, 'Singapore', 'https://www.carrotsandsticks.org/policies/160_11', ARRAY['sdg13', 'regulations', 'mandatory', 'singapore', 'sdg16', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('93ea19c2-030e-5ea5-a953-bd5f7a83f93a', 'Singapore Practice Note 7.6 Sustainability Reporting Guide', 'Practice Note 7.6 Sustainability Reporting Guide', 'The Singapore Exchange (SGX) requires all issuers to prepare an annual sustainability report in compliance with Listing Rule 711A, which outlines the primary components of sustainability practices that should be included in the report. The Sustainability Reporting Guide provides guidance on the structure and content of the report. It should be noted that sustainability reporting does not exempt the issuer from disclosing any information that could affect the value of its securities or establish a false market. The Policy Statement on Sustainability Reporting explains that investors increasingly demand sustainability information to supplement financial reports. The addition of sustainability reporting provides a comprehensive picture of the issuer, including environmental, social, and governance (ESG) factors. The combined financial and sustainability reports provide a better assessment of the issuer''s financial prospects and management quality.', 'The Singapore Exchange (SGX) requires all issuers to prepare an annual sustainability report in compliance with Listing Rule 711A, which outlines the primary components of sustainability practices that should be included in the report. The Sustainability Reporting Guide provides guidance on the structure and content of the report. It should be noted that sustainability reporting does not exempt the issuer from disclosing any information that could affect the value of its securities or establish a false market. The Policy Statement on Sustainability Reporting explains that investors increasingly demand sustainability information to supplement financial reports. The addition of sustainability reporting provides a comprehensive picture of the issuer, including environmental, social, and governance (ESG) factors. The combined financial and sustainability reports provide a better assessment of the issuer''s financial prospects and management quality.', 'The Singapore Exchange (SGX) requires all issuers to prepare an annual sustainability report in compliance with Listing Rule 711A, which outlines the primary components of sustainability practices that should be included in the report. The Sustainability Reporting Guide provides guidance on the structure and content of the report. It should be noted that sustainability reporting does not exempt the issuer from disclosing any information that could affect the value of its securities or establish a false market. The Policy Statement on Sustainability Reporting explains that investors increasingly demand sustainability information to supplement financial reports. The addition of sustainability reporting provides a comprehensive picture of the issuer, including environmental, social, and governance (ESG) factors. The combined financial and sustainability reports provide a better assessment of the issuer''s financial prospects and management quality.', 'Singapore', 'climate', 'in_force', '2016-01-01'::date, 'Singapore', 'https://www.carrotsandsticks.org/policies/160_15', ARRAY['regulations', 'mandatory', 'singapore', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('845f5e6f-8045-5441-a7ab-f1e4b02baf8f', 'Singapore Stewardship Principles (SSP) for Responsible Investors', 'Singapore Stewardship Principles (SSP) for Responsible Investors, 2016', 'These Stewardship Principles aim, by articulating the core behaviour and actions associated with investor stewardship, to enable investors to be active and responsible shareholders. They provide a view on the activities and functions that stewards should carry out, and how these should relate to the boards and management of investee companies.', 'These Stewardship Principles aim, by articulating the core behaviour and actions associated with investor stewardship, to enable investors to be active and responsible shareholders. They provide a view on the activities and functions that stewards should carry out, and how these should relate to the boards and management of investee companies.', 'These Stewardship Principles aim, by articulating the core behaviour and actions associated with investor stewardship, to enable investors to be active and responsible shareholders. They provide a view on the activities and functions that stewards should carry out, and how these should relate to the boards and management of investee companies.', 'Singapore', 'governance', 'in_force', '2016-01-01'::date, 'Singapore', 'https://www.carrotsandsticks.org/policies/160_5', ARRAY['guidance_frameworks', 'voluntary', 'singapore', 'other sustainability policy']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1650035b-ecf6-53f5-bb9e-1f7915a29c88', 'Singapore Code of Corporate Governance', 'Code of Corporate Governance, 2012', 'This dovument outlines the 2012 version of the Code of Corporate Governance in Singapore.', 'This dovument outlines the 2012 version of the Code of Corporate Governance in Singapore.', 'This dovument outlines the 2012 version of the Code of Corporate Governance in Singapore.', 'Singapore', 'governance', 'in_force', '2012-01-01'::date, 'Singapore', 'https://www.carrotsandsticks.org/policies/160_1', ARRAY['other sustainability policy', 'mandatory', 'singapore', 'sdg16', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('79fab39e-0c2a-58db-a205-14b99d96dff9', 'Singapore Energy Conservation Act 2012 ( of', 'Energy Conservation Act 2012 (No. 11 of 2012)', 'This document outlines an Act to mandate energy efficiency requirements and energy management practices to promote energy conservation, improve energy efficiency and reduce environmental impact, and to make consequential and related amendments to certain other written laws.', 'This document outlines an Act to mandate energy efficiency requirements and energy management practices to promote energy conservation, improve energy efficiency and reduce environmental impact, and to make consequential and related amendments to certain other written laws.', 'This document outlines an Act to mandate energy efficiency requirements and energy management practices to promote energy conservation, improve energy efficiency and reduce environmental impact, and to make consequential and related amendments to certain other written laws.', 'Singapore', 'climate', 'in_force', '2012-01-01'::date, 'Singapore', 'https://www.carrotsandsticks.org/policies/160_4', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'singapore']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a89ed350-abc2-5b09-8981-e93990db57e4', 'Singapore Guide to Sustainability Reporting for Listed Companies', 'Guide to Sustainability Reporting for Listed Companies, 2011', 'This Policy Statement describes sustainability reporting and sets out broad principles to guide listed companies in formulating their sustainability reporting frameworks.', 'This Policy Statement describes sustainability reporting and sets out broad principles to guide listed companies in formulating their sustainability reporting frameworks.', 'This Policy Statement describes sustainability reporting and sets out broad principles to guide listed companies in formulating their sustainability reporting frameworks.', 'Singapore', 'climate', 'in_force', '2011-01-01'::date, 'Singapore', 'https://www.carrotsandsticks.org/policies/160_3', ARRAY['sdg13', 'mandatory', 'singapore', 'sdg16', 'mandatory_regulations', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d9bf1bff-604f-51b6-8a0f-1e871feee9f9', 'Singapore Corporate Governance for Banks, Financial Holding Companies', 'Guidelines on Corporate Governance for Banks, Financial Holding Companies and Direct Insurers which are incorporated in Singapore, 2010', 'The Guidelines on Corporate Governance (“The Guidelines”) are relevant to all banks, financial holding companies and direct insurers, which are incorporated in Singapore (“Financial Institutions”). They provide guidance on best practices that a bank, financial holding company or direct insurer should strive to achieve in relation to its corporate governance.', 'The Guidelines on Corporate Governance (“The Guidelines”) are relevant to all banks, financial holding companies and direct insurers, which are incorporated in Singapore (“Financial Institutions”). They provide guidance on best practices that a bank, financial holding company or direct insurer should strive to achieve in relation to its corporate governance.', 'The Guidelines on Corporate Governance (“The Guidelines”) are relevant to all banks, financial holding companies and direct insurers, which are incorporated in Singapore (“Financial Institutions”). They provide guidance on best practices that a bank, financial holding company or direct insurer should strive to achieve in relation to its corporate governance.', 'Singapore', 'governance', 'in_force', '2010-01-01'::date, 'Singapore', 'https://www.carrotsandsticks.org/policies/160_9', ARRAY['guidance_frameworks', 'other sustainability policy', 'singapore', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('64a3b963-0024-5730-8f5a-30588d053483', 'Singapore Code of Corporate Governance 2005 - Board Matters', 'Code of Corporate Governance 2005 - Board Matters', 'The Code of Corporate Governance 2005 issued by the Ministry of Finance supersedes and replaces the Code that was issued in March 2001. The Code of Corporate Governance 2005 takes effect from AGMs held on or after 1 January 2007.', 'The Code of Corporate Governance 2005 issued by the Ministry of Finance supersedes and replaces the Code that was issued in March 2001. The Code of Corporate Governance 2005 takes effect from AGMs held on or after 1 January 2007.', 'The Code of Corporate Governance 2005 issued by the Ministry of Finance supersedes and replaces the Code that was issued in March 2001. The Code of Corporate Governance 2005 takes effect from AGMs held on or after 1 January 2007.', 'Singapore', 'governance', 'in_force', '2005-01-01'::date, 'Singapore', 'https://www.carrotsandsticks.org/policies/160_7', ARRAY['other sustainability policy', 'mandatory', 'singapore', 'sdg16', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('38037e77-31eb-5098-a60d-20ac1e2b6628', 'Singapore Consultation Paper Proposed Revisions to the Code', 'Consultation Paper Proposed Revisions to the Code of Corporate Governance, 2004', 'This consultation paper sets out proposed revisions on the structure of the Code, board matters, remuneration matters, accountability and audit, as well as communication with shareholders.', 'This consultation paper sets out proposed revisions on the structure of the Code, board matters, remuneration matters, accountability and audit, as well as communication with shareholders.', 'This consultation paper sets out proposed revisions on the structure of the Code, board matters, remuneration matters, accountability and audit, as well as communication with shareholders.', 'Singapore', 'governance', 'in_force', '2004-01-01'::date, 'Singapore', 'https://www.carrotsandsticks.org/policies/160_10', ARRAY['other sustainability policy', 'mandatory', 'singapore', 'sdg16', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('432faca9-5581-5f70-903b-f4a77d6109e1', 'Slovakia Act Law of June 10, 2025 amending Act', 'Act No. 187/2025  Law of June 10, 2025 amending Act No. 566/2001 Coll.', 'Act No. 187/2025 amends the existing securities and investment services law in Slovakia, introducing new requirements for transparency and information disclosure. It mandates that members of a subgroup must inform on their website whether they have entered into a group support contract and provide a description of the general conditions of this contract. This information must be updated at least annually. The law applies to financial market participants and is designed to enhance transparency in financial services. The provisions will first be applied from January 10, 2030, indicating a future implementation timeline.', 'Act No. 187/2025 amends the existing securities and investment services law in Slovakia, introducing new requirements for transparency and information disclosure. It mandates that members of a subgroup must inform on their website whether they have entered into a group support contract and provide a description of the general conditions of this contract. This information must be updated at least annually. The law applies to financial market participants and is designed to enhance transparency in financial services. The provisions will first be applied from January 10, 2030, indicating a future implementation timeline.', 'Act No. 187/2025 amends the existing securities and investment services law in Slovakia, introducing new requirements for transparency and information disclosure. It mandates that members of a subgroup must inform on their website whether they have entered into a group support contract and provide a description of the general conditions of this contract. This information must be updated at least annually. The law applies to financial market participants and is designed to enhance transparency in financial services. The provisions will first be applied from January 10, 2030, indicating a future implementation timeline.', 'Slovakia', 'climate', 'in_force', '2025-01-01'::date, 'Slovakia', 'https://www.carrotsandsticks.org/policies/162_12', ARRAY['regulations', 'slovakia', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('00d3dcfa-40b2-54c9-acaa-515f64c0fb63', 'Slovakia Draft Act of 2025 on the application', 'Draft Act of 2025 on the application of the principle of equal pay for men and women for equal work or work of equal value and on the amendment and supplementation of certain laws', 'The Draft Act of 2025 in Slovakia focuses on ensuring equal pay for men and women for equal work. It prohibits discrimination and allows for differentiated pay based on objective criteria. The policy applies to various employment relationships, emphasizing equal treatment and nondiscrimination for all genders.', 'The Draft Act of 2025 in Slovakia focuses on ensuring equal pay for men and women for equal work. It prohibits discrimination and allows for differentiated pay based on objective criteria. The policy applies to various employment relationships, emphasizing equal treatment and nondiscrimination for all genders.', 'The Draft Act of 2025 in Slovakia focuses on ensuring equal pay for men and women for equal work. It prohibits discrimination and allows for differentiated pay based on objective criteria. The policy applies to various employment relationships, emphasizing equal treatment and nondiscrimination for all genders.', 'Slovakia', 'social', 'in_force', '2025-01-01'::date, 'Slovakia', 'https://www.carrotsandsticks.org/policies/162_9', ARRAY['sdg8', 'sdg10', 'regulations', 'slovakia', 'mandatory', 'sdg5']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e9e0bc24-0778-5a45-a47f-06fdeac6b174', 'Slovakia Law of 24 April 2024, amending Act Coll', 'Law of 24 April 2024, amending Act No. 431/2002 Coll. on Accounting as amended and amending certain acts', 'The Law of 24 April 2024 in Slovakia amends accounting regulations to include sustainability aspects and increase financial thresholds. It affects various financial institutions and entities by updating reporting requirements and financial limits.', 'The Law of 24 April 2024 in Slovakia amends accounting regulations to include sustainability aspects and increase financial thresholds. It affects various financial institutions and entities by updating reporting requirements and financial limits.', 'The Law of 24 April 2024 in Slovakia amends accounting regulations to include sustainability aspects and increase financial thresholds. It affects various financial institutions and entities by updating reporting requirements and financial limits.', 'Slovakia', 'climate', 'in_force', '2024-01-01'::date, 'Slovakia', 'https://www.carrotsandsticks.org/policies/162_10', ARRAY['sdg13', 'regulations', 'slovakia', 'mandatory', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9090e271-f304-5fb4-8e0f-7510c85e739d', 'Slovakia Decree of 26 June 2024 No. MF/-74 on', 'Decree of 26 June 2024 No. MF/009347/2024-74 on assurance', 'The Decree of 26 June 2024 establishes the examination procedures for assurance in sustainability reporting in Slovakia. It mandates that applicants for assurance examinations must submit specific documentation, including proof of professional training and continuous education in sustainability. The examinations are conducted annually in November, with applications due by the end of June. This policy applies to statutory auditors and aims to ensure competence in sustainability reporting practices. The requirements are mandatory for those seeking to perform assurance in this field.', 'The Decree of 26 June 2024 establishes the examination procedures for assurance in sustainability reporting in Slovakia. It mandates that applicants for assurance examinations must submit specific documentation, including proof of professional training and continuous education in sustainability. The examinations are conducted annually in November, with applications due by the end of June. This policy applies to statutory auditors and aims to ensure competence in sustainability reporting practices. The requirements are mandatory for those seeking to perform assurance in this field.', 'The Decree of 26 June 2024 establishes the examination procedures for assurance in sustainability reporting in Slovakia. It mandates that applicants for assurance examinations must submit specific documentation, including proof of professional training and continuous education in sustainability. The examinations are conducted annually in November, with applications due by the end of June. This policy applies to statutory auditors and aims to ensure competence in sustainability reporting practices. The requirements are mandatory for those seeking to perform assurance in this field.', 'Slovakia', 'climate', 'in_force', '2024-01-01'::date, 'Slovakia', 'https://www.carrotsandsticks.org/policies/162_11', ARRAY['sdg4', 'other sustainability policy', 'regulations', 'slovakia', 'mandatory']::text[]) ON CONFLICT (id) DO NOTHING;
