INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('73a4bf34-49b7-5e14-aeba-a423093b1288', 'Slovakia Occupational Safety and Health Protection Act - Collection', 'Occupational Safety and Health Protection Act - Collection of Laws Years 2006-2011', 'This Act lays down the general principles of prevention and the basic conditions for the purposes of ensuring occupational safety and health protection, and for avoiding risks and factors causing occupational accidents, occupational diseases and other damage to health from work.', 'This Act lays down the general principles of prevention and the basic conditions for the purposes of ensuring occupational safety and health protection, and for avoiding risks and factors causing occupational accidents, occupational diseases and other damage to health from work.', 'This Act lays down the general principles of prevention and the basic conditions for the purposes of ensuring occupational safety and health protection, and for avoiding risks and factors causing occupational accidents, occupational diseases and other damage to health from work.', 'Slovakia', 'nature', 'in_force', '2011-01-01'::date, 'Slovakia', 'https://www.carrotsandsticks.org/policies/162_8', ARRAY['sdg8', 'sdg14', 'regulations', 'slovakia', 'mandatory', 'disclosure', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
